from datetime import date
job = [
    {"emp": "E100", "dept": "인사팀",   "start": date(2024, 3, 1), "end": date(2025, 6, 30)},
    {"emp": "E100", "dept": "HR기획팀", "start": date(2025, 7, 1), "end": date(9999, 12, 31)},
]
def as_of(emp, d):
    return next(r["dept"] for r in job if r["emp"] == emp and r["start"] <= d <= r["end"])
print(as_of("E100", date(2025, 6, 30)), as_of("E100", date(2025, 7, 1)))
# 인사팀 HR기획팀

from decimal import Decimal as D, ROUND_DOWN
RATES = {  # 근로자 부담분 — 해마다 바뀌니 연도별 표로
    2025: {"pension": D("0.045"),  "health": D("0.03545"), "ltc_ratio": D("0.9182") / D("7.09"), "employ": D("0.009")},
    2026: {"pension": D("0.0475"), "health": D("0.03595"), "ltc_ratio": D("0.9448") / D("7.19"), "employ": D("0.009")},
}
def won(x): return x.quantize(D("1"), rounding=ROUND_DOWN)
def deductions(monthly, year):
    r = RATES[year]; health = won(monthly * r["health"])
    return {"국민연금": won(monthly * r["pension"]), "건강보험": health,
            "장기요양": won(health * r["ltc_ratio"]), "고용보험": won(monthly * r["employ"])}
def overtime(monthly_ordinary, hours):
    return won(monthly_ordinary / D(209) * D("1.5") * hours)
pay = D(4_000_000)
for y in (2025, 2026):
    d = deductions(pay, y); print(y, d, "합계", sum(d.values()))
print("연장 10시간 수당", overtime(pay, 10))
